  PyArrayObject *out = (PyArrayObject *)PyArray_SimpleNew(ndim-1, PyArray_DIMS(samples), NPY_DOUBLE);
  if (!out) { Py_DECREF(samples); return NULL; }
  int status = gpython_coulomb_log(PyArray_SIZE(out), PyArray_DATA(samples), ms, mr, qs, qr,
